"use client";
import {
  Button,
  ButtonGroup,
  Heading,
  Select,
  Stack,
  Switch,
  FieldError,
} from "@openboa/yogurt";
export type Preferences = { digest: "daily" | "weekly"; notify: boolean };
export function ProjectSettings({
  draft,
  saved,
  pending = false,
  error,
  onChange,
  onSave,
}: {
  draft: Preferences;
  saved: Preferences;
  pending?: boolean;
  error?: string;
  onChange: (draft: Preferences) => void;
  onSave: (draft: Preferences) => void;
}) {
  const dirty = draft.digest !== saved.digest || draft.notify !== saved.notify;
  return (
    <form
      aria-label="Project settings"
      onSubmit={(e) => {
        e.preventDefault();
        if (dirty && !pending) onSave(draft);
      }}
    >
      <Stack gap={16}>
        <Heading>Project settings</Heading>
        <Switch
          label="Send a digest"
          checked={draft.notify}
          disabled={pending}
          onCheckedChange={(notify) => onChange({ ...draft, notify })}
        />
        <Select
          label="Frequency"
          value={draft.digest}
          disabled={pending || !draft.notify}
          options={[
            { id: "daily", label: "Daily" },
            { id: "weekly", label: "Weekly" },
          ]}
          onChange={(e) =>
            onChange({
              ...draft,
              digest: e.target.value as Preferences["digest"],
            })
          }
        />
        {error && <FieldError role="alert">{error}</FieldError>}
        <ButtonGroup label="Settings actions">
          <Button
            type="submit"
            disabled={!dirty}
            pending={pending}
            pendingLabel="Saving"
          >
            Save changes
          </Button>
          <Button
            emphasis="quiet"
            disabled={!dirty || pending}
            onClick={() => onChange(saved)}
          >
            Discard
          </Button>
        </ButtonGroup>
      </Stack>
    </form>
  );
}

"use client";
import { useState } from "react";
import {
  Count,
  EmptyResult,
  FilterBar,
  List,
  ListHeader,
  ListRow,
  Stack,
  Toggle,
} from "@openboa/yogurt";
export interface BrowserRecord {
  id: string;
  title: string;
  detail: string;
  archived?: boolean;
}
export function CollectionBrowser({
  title,
  records,
  onOpen,
}: {
  title: string;
  records: BrowserRecord[];
  onOpen: (id: string) => void;
}) {
  const [query, setQuery] = useState(""),
    [archives, setArchives] = useState(false);
  const shown = records.filter(
    (r) =>
      (archives || !r.archived) &&
      (r.title + " " + r.detail)
        .toLowerCase()
        .includes(query.trim().toLowerCase()),
  );
  return (
    <Stack gap={12}>
      <ListHeader
        title={title}
        action={<Count value={shown.length} label="views" />}
      />
      <FilterBar label="Find a view" query={query} onQueryChange={setQuery}>
        <Toggle pressed={archives} onPressedChange={setArchives}>
          Include archived
        </Toggle>
      </FilterBar>
      {shown.length ? (
        <List label={title}>
          {shown.map((r) => (
            <ListRow
              key={r.id}
              title={r.title}
              description={r.detail}
              onActivate={() => onOpen(r.id)}
            />
          ))}
        </List>
      ) : (
        <EmptyResult
          query={query}
          empty="No views yet"
          onClear={() => setQuery("")}
        />
      )}
    </Stack>
  );
}

"use client";
import { useState } from "react";
import {
  Button,
  ConfirmDialog,
  RecordFacts,
  Stack,
  Status,
  type Decision,
  type DecisionRef,
  type Fact,
  type Observation,
} from "@openboa/yogurt";
export function DecisionReview({
  title,
  facts,
  observation,
  decision,
  onConfirm,
  pending = false,
  result,
}: {
  title: string;
  facts: Fact[];
  observation: Observation;
  decision: Decision;
  onConfirm: (original: DecisionRef) => void;
  pending?: boolean;
  result?: string;
}) {
  const [open, setOpen] = useState(false);
  return (
    <Stack gap={16}>
      <RecordFacts title={title} facts={facts} {...observation} />
      {result && <Status>{result}</Status>}
      <Button
        emphasis="soft"
        tone="danger"
        disabled={!decision.available}
        pending={pending}
        onClick={() => setOpen(true)}
      >
        {decision.confirmLabel}
      </Button>
      <ConfirmDialog
        decision={decision}
        open={open}
        onOpenChange={setOpen}
        onConfirm={onConfirm}
        pending={pending}
      />
    </Stack>
  );
}

"use client";
import {
  Button,
  ButtonGroup,
  Message,
  Stack,
  Textarea,
  Transcript,
} from "@openboa/yogurt";
export interface ThreadMessage {
  id: string;
  speaker: string;
  body: string;
  time?: string;
  dateTime?: string;
}
export function ConversationPanel({
  messages,
  revision,
  draft,
  onDraftChange,
  onSend,
  pending = false,
  onStop,
}: {
  messages: ThreadMessage[];
  revision: string | number;
  draft: string;
  onDraftChange: (value: string) => void;
  onSend: (value: string) => void;
  pending?: boolean;
  onStop?: () => void;
}) {
  const ready = !!draft.trim() && !pending;
  function send() {
    if (ready) onSend(draft.trim());
  }
  return (
    <Stack gap={16}>
      <Transcript label="Conversation" revision={revision}>
        {messages.map((m) => (
          <Message
            key={m.id}
            speaker={m.speaker}
            time={m.time}
            dateTime={m.dateTime}
          >
            {m.body}
          </Message>
        ))}
      </Transcript>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          send();
        }}
      >
        <Stack>
          <Textarea
            label="Message"
            value={draft}
            onChange={(e) => onDraftChange(e.target.value)}
            onKeyDown={(e) => {
              if (
                e.key === "Enter" &&
                (e.metaKey || e.ctrlKey) &&
                !e.nativeEvent.isComposing
              ) {
                e.preventDefault();
                send();
              }
            }}
          />
          <ButtonGroup label="Message actions">
            <Button type="submit" disabled={!ready}>
              Send
            </Button>
            {pending && onStop && (
              <Button emphasis="quiet" onClick={onStop}>
                Stop
              </Button>
            )}
          </ButtonGroup>
        </Stack>
      </form>
    </Stack>
  );
}

"use client";

import { useId, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import {
  AgentAvatar,
  AgentRow,
  Button,
  Heading,
  IconButton,
  SearchField,
  Stack,
  Text,
  agentPresenceLabels,
  type AgentSummary,
} from "@openboa/yogurt";

interface WorkspaceDetailProps {
  agent: AgentSummary;
  rosterId: string;
  rosterOpen: boolean;
  onOpenRoster: () => void;
  renderConversation: (agent: AgentSummary) => ReactNode;
  renderRuntime?: (agent: AgentSummary) => ReactNode;
}

function WorkspaceDetail({
  agent,
  rosterId,
  rosterOpen,
  onOpenRoster,
  renderConversation,
  renderRuntime,
}: WorkspaceDetailProps) {
  const headingId = useId();
  const inspectorId = useId();
  const inspectorButton = useRef<HTMLButtonElement>(null);
  const [inspectorOpen, setInspectorOpen] = useState(false);
  const runtime = inspectorOpen && renderRuntime?.(agent);
  const avatar = agent.avatar ?? (agent.art && (
    <AgentAvatar
      agent={agent.art}
      size={40}
      state={agent.state}
    />
  ));
  return (
    <section aria-labelledby={headingId} className="yg-agent-detail">
      <div className="yg-agent-detail-grid" data-inspector={!!runtime}>
        <header className="yg-agent-detail-header">
          <IconButton
            label="Browse agents"
            icon="menu"
            className="yg-agent-roster-toggle"
            aria-controls={rosterId}
            aria-expanded={rosterOpen}
            onClick={onOpenRoster}
          />
          {avatar && <span className="yg-agent-detail-art" aria-hidden="true">{avatar}</span>}
          <div className="yg-agent-detail-identity">
            <Heading id={headingId} data-agent-heading="" level={3} tabIndex={-1}>{agent.name}</Heading>
            <Text variant="help" role="status">
              {agent.role ? agent.role + " · " : ""}{agentPresenceLabels[agent.state]}
            </Text>
          </div>
          {renderRuntime && (
            <Button
              ref={inspectorButton}
              emphasis="quiet"
              aria-expanded={inspectorOpen}
              aria-controls={inspectorId}
              onClick={() => setInspectorOpen((value) => !value)}
            >
              {inspectorOpen ? "Hide computer" : "Computer"}
            </Button>
          )}
        </header>
        {renderRuntime && (
          <aside id={inspectorId} className="yg-agent-inspector" aria-label="Computer inspector" hidden={!runtime}>
            {runtime && (
              <>
                <div className="yg-agent-inspector-close">
                  <IconButton
                    label="Close computer"
                    icon="close"
                    onClick={() => {
                      setInspectorOpen(false);
                      inspectorButton.current?.focus();
                    }}
                  />
                </div>
                {runtime}
              </>
            )}
          </aside>
        )}
        <div className="yg-agent-conversation">{renderConversation(agent)}</div>
      </div>
    </section>
  );
}

export function AgentWorkspace({
  agents,
  currentId,
  onSelectAgent,
  renderConversation,
  renderRuntime,
}: {
  agents: readonly AgentSummary[];
  currentId?: string;
  onSelectAgent: (id: string) => void;
  renderConversation: (agent: AgentSummary) => ReactNode;
  renderRuntime?: (agent: AgentSummary) => ReactNode;
}) {
  const rosterId = useId();
  const workspace = useRef<HTMLElement>(null);
  const roster = useRef<HTMLElement>(null);
  const focusOnClose = useRef(false);
  const [query, setQuery] = useState("");
  const [rosterOpen, setRosterOpen] = useState(false);
  const current = agents.find((agent) => agent.id === currentId);
  const term = query.trim().toLocaleLowerCase("en");
  const pinned: AgentSummary[] = [];
  const grouped = new Map<string, AgentSummary[]>();
  for (const agent of agents) {
    const searchable = [agent.name, agent.role, agent.group].join(" ").toLocaleLowerCase("en");
    if (!searchable.includes(term)) continue;
    if (agent.pinned) {
      pinned.push(agent);
    } else {
      const group = agent.group ?? "";
      const groupAgents = grouped.get(group) ?? [];
      groupAgents.push(agent);
      grouped.set(group, groupAgents);
    }
  }
  const sections = [
    ...(pinned.length ? [{ key: "pinned", title: "Pinned", agents: pinned }] : []),
    ...Array.from(grouped, ([title, groupAgents]) => ({ key: "group-" + title, title, agents: groupAgents })),
  ];

  useLayoutEffect(() => {
    if (rosterOpen) roster.current?.querySelector<HTMLInputElement>("input[type='search']")?.focus();
    else if (focusOnClose.current) {
      focusOnClose.current = false;
      workspace.current?.querySelector<HTMLElement>("[data-agent-heading]")?.focus();
    }
  }, [rosterOpen, currentId]);

  function closeRoster() {
    if (rosterOpen) focusOnClose.current = true;
    setRosterOpen(false);
  }

  return (
    <section
      ref={workspace}
      aria-label="Agent workspace"
      className="yg-agent-workspace"
      data-roster-open={rosterOpen}
      data-has-agent={!!current}
    >
      <div className="yg-agent-workspace-grid">
        <nav id={rosterId} ref={roster} aria-label="Agent roster" className="yg-agent-roster">
          <Stack gap={12}>
            <header className="yg-agent-roster-header">
              <Heading level={3}>Agents</Heading>
              {current && rosterOpen && (
                <IconButton icon="close" label="Close agent roster" className="yg-agent-roster-toggle" onClick={closeRoster} />
              )}
            </header>
            <SearchField label="Find an agent" value={query} onValueChange={setQuery} />
            {sections.length === 0 && (
              <Stack gap={8} className="yg-agent-empty">
                <Text variant="help">{term ? "No matching agents." : "No agents available."}</Text>
                {term && <Button emphasis="soft" onClick={() => setQuery("")}>Show all agents</Button>}
              </Stack>
            )}
            {sections.map((section) => (
              <section key={section.key} className="yg-agent-group" aria-label={section.title || "Available agents"}>
                {section.title && <h4>{section.title}</h4>}
                <ul>
                  {section.agents.map((agent) => (
                    <li key={agent.id}>
                      <AgentRow
                        agent={agent}
                        current={agent.id === current?.id}
                        onSelect={(id) => {
                          closeRoster();
                          onSelectAgent(id);
                        }}
                      />
                    </li>
                  ))}
                </ul>
              </section>
            ))}
          </Stack>
        </nav>
        {current ? (
          <WorkspaceDetail
            key={current.id}
            agent={current}
            rosterId={rosterId}
            rosterOpen={rosterOpen}
            onOpenRoster={() => setRosterOpen(true)}
            renderConversation={renderConversation}
            renderRuntime={renderRuntime}
          />
        ) : agents.length > 0 && (
          <div className="yg-agent-empty yg-agent-empty-selection">
            <Text variant="help">Choose an agent to open its conversation.</Text>
          </div>
        )}
      </div>
    </section>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import {
  Button,
  EmptyResult,
  FilterBar,
  Heading,
  List,
  ProjectMark,
  ResourceRow,
  Result,
  SearchField,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarItem,
  SidebarLayout,
  SidebarTrigger,
  Stack,
  Tabs,
  ThreadRow,
  resourceLabels,
  type Project,
  type WorkspaceResource,
  type WorkspaceThread,
} from "@openboa/yogurt";

export interface WorkspaceProject {
  id: string;
  title: string;
  description?: string;
  mark?: Project;
  threads: readonly WorkspaceThread[];
  sources: readonly WorkspaceResource[];
  instructions?: string;
}

export interface ProjectWorkspaceProps {
  projects: readonly WorkspaceProject[];
  projectId: string | null;
  onProjectChange: (projectId: string) => void;
  selection?: { projectId: string; threadId?: string; sourceId?: string };
  onOpenThread?: (projectId: string, threadId: string) => void;
  onOpenSource?: (projectId: string, sourceId: string) => void;
  onPinSource?: (projectId: string, sourceId: string, pinned: boolean) => void;
  onNewChat?: (projectId: string) => void;
  onAddSource?: (projectId: string) => void;
  onEditInstructions?: (projectId: string) => void;
  onShare?: (projectId: string) => void;
  onCreateProject?: () => void;
  composer?: (projectId: string) => ReactNode;
}

function matches(query: string, ...fields: (string | undefined)[]) {
  return fields.join(" ").toLowerCase().includes(query.trim().toLowerCase());
}

function ProjectView({
  project,
  selection,
  onOpenThread,
  onOpenSource,
  onPinSource,
  onNewChat,
  onAddSource,
  onEditInstructions,
  onShare,
  composer,
}: Omit<ProjectWorkspaceProps, "projects" | "projectId" | "onProjectChange" | "onCreateProject"> & {
  project: WorkspaceProject;
}) {
  const [tab, setTab] = useState("chats");
  const [threadSearch, setThreadSearch] = useState("");
  const [sourceSearch, setSourceSearch] = useState("");
  const threads = project.threads.filter((row) => matches(threadSearch, row.title, row.preview));
  const sources = project.sources.filter((row) => matches(sourceSearch, row.title, resourceLabels[row.kind], row.detail));
  const current = selection?.projectId === project.id ? selection : undefined;
  const newChat = onNewChat && (
    <Button emphasis="soft" onClick={() => onNewChat(project.id)}>New chat</Button>
  );
  const addSource = onAddSource && (
    <Button emphasis="soft" onClick={() => onAddSource(project.id)}>Add source</Button>
  );
  const editInstructions = onEditInstructions && (
    <Button emphasis="soft" onClick={() => onEditInstructions(project.id)}>Edit instructions</Button>
  );

  return (
    <Stack gap={24} className="yg-project-view">
      <header className="yg-project-header">
        <div className="yg-project-identity">
          {project.mark && <ProjectMark project={project.mark} label="" />}
          <div>
            <Heading>{project.title}</Heading>
            {project.description && <p className="yg-project-description">{project.description}</p>}
          </div>
        </div>
        {onShare && (
          <Button emphasis="quiet" onClick={() => onShare(project.id)}>Share</Button>
        )}
      </header>
      <Tabs
        label="Project content"
        value={tab}
        onValueChange={setTab}
        items={[
          {
            id: "chats",
            label: "Chats",
            panel: (
              <Stack gap={12}>
                {composer?.(project.id)}
                {project.threads.length > 0 && (
                  <FilterBar label="Find a project chat" query={threadSearch} onQueryChange={setThreadSearch}>
                    {newChat}
                  </FilterBar>
                )}
                {threads.length > 0 ? (
                  <List label={project.title + " chats"}>
                    {threads.map((thread) => (
                      <ThreadRow
                        key={thread.id}
                        thread={thread}
                        selected={thread.id === current?.threadId}
                        onOpen={onOpenThread && ((id) => onOpenThread(project.id, id))}
                      />
                    ))}
                  </List>
                ) : threadSearch.trim() ? (
                  <EmptyResult query={threadSearch} onClear={() => setThreadSearch("")} />
                ) : (
                  <Result title="No project chats yet" action={newChat}>
                    Start a chat with this project's context.
                  </Result>
                )}
              </Stack>
            ),
          },
          {
            id: "sources",
            label: "Sources",
            panel: (
              <Stack gap={12}>
                {project.sources.length > 0 && (
                  <FilterBar label="Find a project source" query={sourceSearch} onQueryChange={setSourceSearch}>
                    {addSource}
                  </FilterBar>
                )}
                {sources.length > 0 ? (
                  <List label={project.title + " sources"}>
                    {sources.map((resource) => (
                      <ResourceRow
                        key={resource.id}
                        resource={resource}
                        selected={resource.id === current?.sourceId}
                        onOpen={onOpenSource && ((id) => onOpenSource(project.id, id))}
                        onPinChange={onPinSource && ((id, pinned) => onPinSource(project.id, id, pinned))}
                      />
                    ))}
                  </List>
                ) : sourceSearch.trim() ? (
                  <EmptyResult query={sourceSearch} onClear={() => setSourceSearch("")} />
                ) : (
                  <Result title="No project sources yet" action={addSource}>
                    Add files, links or saved work for this project.
                  </Result>
                )}
              </Stack>
            ),
          },
          {
            id: "instructions",
            label: "Instructions",
            panel: project.instructions ? (
              <Stack gap={12}>
                <p className="yg-project-instructions">{project.instructions}</p>
                {editInstructions && <div>{editInstructions}</div>}
              </Stack>
            ) : (
              <Result title="No instructions yet" action={editInstructions}>
                Set guidelines for conversations in this project.
              </Result>
            ),
          },
        ]}
      />
    </Stack>
  );
}

export function ProjectWorkspace({
  projects,
  projectId,
  onProjectChange,
  onCreateProject,
  ...view
}: ProjectWorkspaceProps) {
  const [query, setQuery] = useState("");
  const project = projects.find((row) => row.id === projectId);
  const shown = projects.filter((row) => matches(query, row.title, row.description));
  return (
    <section aria-label="Project workspace" className="yg-project-workspace">
      <SidebarLayout label="Project directory" width="13rem" navigation={
        <>
          <SidebarHeader><Heading level={3}>Projects</Heading></SidebarHeader>
          {projects.length > 0 && (
            <SidebarHeader><SearchField label="Find a project" value={query} onValueChange={setQuery} /></SidebarHeader>
          )}
          <SidebarContent label="Available projects">
            {shown.map((row) => (
              <SidebarItem key={row.id} label={row.title} active={row.id === projectId}
                icon={row.mark && <ProjectMark project={row.mark} label="" size={20} />}
                onSelect={() => onProjectChange(row.id)} />
            ))}
            {!shown.length && query.trim() && <EmptyResult query={query} onClear={() => setQuery("")} />}
          </SidebarContent>
          {onCreateProject && (
            <SidebarFooter><Button emphasis="quiet" onClick={onCreateProject}>New project</Button></SidebarFooter>
          )}
        </>
      }>
        <Stack gap={12}>
          <div><SidebarTrigger label="Projects" showLabel /></div>
          {project ? (
          <ProjectView key={project.id} project={project} {...view} />
          ) : (
          <Result title={projects.length ? "Choose a project" : "No projects available"}>
            {projects.length
              ? "Pick an available project to see its chats and sources."
              : "A project will appear here once it is available to you."}
          </Result>
          )}
        </Stack>
      </SidebarLayout>
    </section>
  );
}

"use client";
import { useState, type ReactNode } from "react";
import {
  Badge,
  Button,
  Count,
  EmptyResult,
  FilterBar,
  ListHeader,
  Result,
  RoutineRow,
  Skeleton,
  Stack,
  Tabs,
  Text,
  type RoutineRecord,
  type Tone,
} from "@openboa/yogurt";

type Category = "routines" | "skills" | "connections";
type CapabilityState = "ready" | "restricted" | "connected" | "disconnected";

export interface CapabilityRecord {
  id: string;
  title: string;
  detail: string;
  state: CapabilityState;
}

const states = {
  ready: { label: "Ready", tone: "success" },
  restricted: { label: "Restricted", tone: "warning" },
  connected: { label: "Connected", tone: "success" },
  disconnected: { label: "Disconnected", tone: "neutral" },
} satisfies Record<CapabilityState, { label: string; tone: Tone }>;

function CapabilityRows({
  group,
  items,
  onInspect,
}: {
  group: "skills" | "connections";
  items: readonly CapabilityRecord[];
  onInspect?: (group: Category, id: string) => void;
}) {
  return (
    <ul className="yg-operations-list" aria-label={group}>
      {items.map((item) => {
        const state = states[item.state];
        return (
          <li className="yg-routine-row" key={item.id}>
            <div className="yg-work-event-content">
              <strong>{item.title}</strong>
              <Text variant="help">{item.detail}</Text>
            </div>
            <div className="yg-operations-actions">
              <Badge tone={state.tone}>{state.label}</Badge>
              {onInspect && (
                <Button
                  emphasis="quiet"
                  size="compact"
                  aria-label={`Inspect ${item.title}`}
                  onClick={() => onInspect(group, item.id)}
                >
                  Details
                </Button>
              )}
            </div>
          </li>
        );
      })}
    </ul>
  );
}

export function OperationsLibrary({
  routines,
  skills,
  connections,
  loading,
  onInspect,
  onEditRoutine,
  onRunRoutine,
  onAdd,
}: {
  routines: readonly RoutineRecord[];
  skills: readonly CapabilityRecord[];
  connections: readonly CapabilityRecord[];
  loading?: boolean;
  onInspect?: (group: Category, id: string) => void;
  onEditRoutine?: (id: string) => void;
  onRunRoutine?: (id: string) => void;
  onAdd?: (group: Category) => void;
}) {
  const [query, setQuery] = useState("");
  const [tab, setTab] = useState<Category>("routines");
  const term = query.trim().toLowerCase();
  const matches = (text: string) => text.toLowerCase().includes(term);
  const visible = {
    routines: routines.filter((r) => matches(`${r.title} ${r.cadence}`)),
    skills: skills.filter((s) => matches(`${s.title} ${s.detail}`)),
    connections: connections.filter((c) => matches(`${c.title} ${c.detail}`)),
  };
  function panel(group: Category, contents: ReactNode) {
    if (loading) return <Skeleton label={`Loading ${group}`} />;
    if (visible[group].length > 0) return contents;
    if (term)
      return <EmptyResult query={query.trim()} onClear={() => setQuery("")} />;
    return (
      <Result
        title={`No ${group} yet`}
        action={
          onAdd && (
            <Button emphasis="soft" onClick={() => onAdd(group)}>
              {group === "routines"
                ? "Add a routine"
